package org.apache.airflow.example;

import static java.lang.System.Logger.Level.INFO;

import java.util.Date;
import org.apache.airflow.sdk.*;
import org.jetbrains.annotations.NotNull;

@SuppressWarnings("DuplicatedCode")
public class InterfaceExampleBuilder {
  private static final System.Logger log =
      System.getLogger(InterfaceExampleBuilder.class.getName());

  public static class Extract implements Task {
    public void execute(@NotNull Context context, Client client) throws Exception {
      log.log(INFO, "Hello from task");

      var pythonInput = client.getXCom("python_task_1");
      log.log(INFO, "Got XCom from python_task_1: {0}", pythonInput);

      var connection = client.getConnection("test_http");
      log.log(INFO, "Got connection: {0}", connection);

      for (var i = 0; i < 3; i++) {
        log.log(INFO, "Beep {0}, next time will be {1}", i, new Date());
        Thread.sleep(2 * 1000);
      }

      client.setXCom(new Date().getTime());
      log.log(INFO, "Goodbye from task");
    }
  }

  public static class TransformInput implements TaskInput {
    public long extracted;
  }

  // The Python Dag file calls transform(extracted), so the field of that name
  // receives the extract task's XCom.
  public static class Transform implements InputTask<TransformInput> {
    public void execute(@NotNull Context context, Client client, TransformInput input) {
      log.log(INFO, "Got extracted value from the bound argument: {0}", input.extracted);

      var variable = client.getVariable("my_variable");
      log.log(INFO, "Got variable: {0}", variable);

      log.log(INFO, "Push XCom to python task 2");
      client.setXCom(new Date().getTime());
    }
  }

  public static class SummarizeInput implements TaskInput {
    // Pinned so the field can be called region rather than regionCode. Or drop
    // it: public String regionCode; binds region_code with nothing declared.
    @ArgName("region_code")
    public String region;

    public long transformed;
  }

  // summarize(region_code=..., transformed=...) is called with keyword
  // arguments, which bind to the fields by name.
  public static class Summarize implements InputTask<SummarizeInput> {
    public void execute(@NotNull Context context, Client client, SummarizeInput input) {
      log.log(
          INFO, "Summarize region {0} for transformed value {1}", input.region, input.transformed);
      if (!"emea".equals(input.region)) {
        throw new RuntimeException("expected region 'emea' but got " + input.region);
      }
    }
  }

  public static DagDef build() {
    return new DagDef("java_interface_example")
        .addTask("extract", Extract.class)
        .addTask("transform", Transform.class)
        .addTask("summarize", Summarize.class);
  }
}

For more information about time handling in Flink and especially event-time, we recommend the general [event-time section]({{< ref "docs/concepts/sql-table-concepts/time_attributes" >}}).

#### Proctime Attributes

In order to declare a proctime attribute in the schema, you can use [Computed Column syntax]({{< ref "docs/sql/reference/ddl/create" >}}#create-table) to declare a computed column which is generated from `PROCTIME()` builtin function.
The computed column is a virtual column which is not stored in the physical data.

{{< tabs "5d1f475b-a002-4e85-84f4-00ab0a55a548" >}}
{{< tab "SQL" >}}
```sql
CREATE TABLE MyTable (
  MyField1 INT,
  MyField2 STRING,
  MyField3 BOOLEAN,
  MyField4 AS PROCTIME() -- declares a proctime attribute
) WITH (
  ...
)
```
{{< /tab >}}
{{< /tabs >}}

#### Rowtime Attributes

In order to control the event-time behavior for tables, Flink provides predefined timestamp extractors and watermark strategies.

Please refer to [CREATE TABLE statements]({{< ref "docs/sql/reference/ddl/create" >}}#create-table) for more information about defining time attributes in DDL.

The following timestamp extractors are supported:

{{< tabs "b40272ba-b259-4a26-9651-815006b283e7" >}}
{{< tab "DDL" >}}
```sql
-- use the existing TIMESTAMP(3) field in schema as the rowtime attribute
CREATE TABLE MyTable (
  ts_field TIMESTAMP(3),
  WATERMARK FOR ts_field AS ...
) WITH (
  ...
)

-- use system functions or UDFs or expressions to extract the expected TIMESTAMP(3) rowtime field
CREATE TABLE MyTable (
  log_ts STRING,
  ts_field AS TO_TIMESTAMP(log_ts),
  WATERMARK FOR ts_field AS ...
) WITH (
  ...
)
```
{{< /tab >}}
{{< /tabs >}}

The following watermark strategies are supported:

{{< tabs "e004ebfb-75b1-4d81-80ff-ac5420744b75" >}}
{{< tab "DDL" >}}
```sql
-- Sets a watermark strategy for strictly ascending rowtime attributes. Emits a watermark of the
-- maximum observed timestamp so far. Rows that have a timestamp bigger to the max timestamp
-- are not late.
CREATE TABLE MyTable (
  ts_field TIMESTAMP(3),
  WATERMARK FOR ts_field AS ts_field
) WITH (
  ...
)

-- Sets a watermark strategy for ascending rowtime attributes. Emits a watermark of the maximum
-- observed timestamp so far minus 1. Rows that have a timestamp bigger or equal to the max timestamp
-- are not late.
CREATE TABLE MyTable (
  ts_field TIMESTAMP(3),
  WATERMARK FOR ts_field AS ts_field - INTERVAL '0.001' SECOND
) WITH (
  ...
)

-- Sets a watermark strategy for rowtime attributes which are out-of-order by a bounded time interval.
-- Emits watermarks which are the maximum observed timestamp minus the specified delay, e.g. 2 seconds.
CREATE TABLE MyTable (
  ts_field TIMESTAMP(3),
  WATERMARK FOR ts_field AS ts_field - INTERVAL '2' SECOND
) WITH (
  ...
)
```
{{< /tab >}}
{{< /tabs >}}

Make sure to always declare both timestamps and watermarks. Watermarks are required for triggering time-based operations.

### SQL Types

Please see the [Data Types]({{< ref "docs/sql/reference/data-types" >}}) page about how to declare a type in SQL.

